(2765213, 383384, 20956, '<td valign="top">Your photo is pixelated, maybe blown up to much. Also dark while the flower is blown out.</td>', 'Your photo is pixelated, maybe blown up to much. Also dark while the flower is blown out.', '2006-08-27 21:35:03.000000', NULL, 1),
(2765217, 381462, 20956, '<td valign="top">Excellent composition, nice crop, very vibrant.</td>', 'Excellent composition, nice crop, very vibrant.', '2006-08-27 21:35:50.000000', NULL, 1),
