(2765358, 382789, 20956, '<td valign="top">Very nice. Her arm seems to be washed out but the rest of the photo is nice.</td>', 'Very nice. Her arm seems to be washed out but the rest of the photo is nice.', '2006-08-27 22:27:50.000000', NULL, 1),
(2765359, 384170, 20956, '<td valign="top">Soft focus not out of focus.</td>', 'Soft focus not out of focus.', '2006-08-27 22:28:12.000000', NULL, 1),
