INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2779951, 384019, 62009, '<td valign="top"><b>Greets from the Critique Club</b> <br/> <br/>This is a pretty nice shot.  I can''t really add anything that hasn''t been told to you already.  I''ve looked at this photo for about 15 minutes trying to find something that I don''t like or is technically wrong.  The only thing I could find is on the lower left, there is something that looks like it might be sensor dust.<br/> <br/>Also, I''m not a huge fan of the borders, but this one matches the photo so well.<br/> <br/>Congrats on lucky number 13...<br/> <br/>If you have any questions or comments, feel free to PM me.<br/> <br/>--Mike</td>', 'Greets from the Critique Club  This is a pretty nice shot.  I can''t really add anything that hasn''t been told to you already.  I''ve looked at this photo for about 15 minutes trying to find something that I don''t like or is technically wrong.  The only thing I could find is on the lower left, there is something that looks like it might be sensor dust. Also, I''m not a huge fan of the borders, but this one matches the photo so well. Congrats on lucky number 13... If you have any questions or comments, feel free to PM me. --Mike', '2006-08-31 21:21:08.000000', NULL, 0),
(2779984, 381784, 19919, '<td valign="top">The pic is great, the DOF is pretty much dead on for this shot, for the challenge though I think a little softer would have worked better.  The cactus itself doesn''t have that softness to it.  This may be attributed to the excellent contrasting colors that don''t allow the softness to come through.  I gave it a 5, but did not think it had enough "softness" to it.  I don''t think the lower right detracts from the shot.<br/> <br/>Ken</td>', 'The pic is great, the DOF is pretty much dead on for this shot, for the challenge though I think a little softer would have worked better.  The cactus itself doesn''t have that softness to it.  This may be attributed to the excellent contrasting colors that don''t allow the softness to come through.  I gave it a 5, but did not think it had enough "softness" to it.  I don''t think the lower right detracts from the shot. Ken', '2006-08-31 21:33:49.000000', NULL, 0),
